modification.replace:
$0
.wrxtHata-reportFlag { width: 72px; text-align: center; white-space: nowrap; }
.wrxtHata-categoryCell { min-width: 150px; }
.wrxtHata-categoryCell .label { display: inline-block; min-width: 82px; text-align: center; }
.wrxtHata-reportContext { margin-top: 4px; }
.wrxtHata-preparedReplyPicker { padding: @xf-paddingMedium; border-top: 1px solid @xf-borderColorLight; }
.wrxtHata-preparedReplyPicker .inputGroup { max-width: 720px; }
.wrxtHata-preparedReplyPicker .formRow-explain { margin-top: 5px; }
.wrxtHata-preparedReplyData { display: none !important; }
@media (max-width: @xf-responsiveMedium) {
    .wrxtHata-reportFlag { width: auto; }
    .wrxtHata-preparedReplyPicker .inputGroup { max-width: none; }
}

$0
@media (max-width: @xf-responsiveMedium) {
    .wrxtHata-reportList .dataList-table,
    .wrxtHata-reportList .dataList-table tbody {
        display: block;
        width: 100%;
        min-width: 0;
        box-sizing: border-box;
    }
    .wrxtHata-reportList .dataList-table thead {
        display: none;
    }
    .wrxtHata-reportList .dataList-table tbody {
        padding: @xf-paddingMedium;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        width: 100%;
        margin: 0 0 @xf-paddingMedium;
        border: 1px solid @xf-borderColorLight;
        border-radius: 6px;
        overflow: hidden;
        box-sizing: border-box;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow:last-child {
        margin-bottom: 0;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td {
        display: block;
        width: auto !important;
        min-width: 0 !important;
        max-width: none !important;
        padding: 9px 11px;
        border: 0;
        border-bottom: 1px solid @xf-borderColorLight;
        box-sizing: border-box;
        white-space: normal !important;
        overflow-wrap: anywhere;
        word-break: normal;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td::before {
        display: block;
        margin-bottom: 4px;
        font-size: 11px;
        line-height: 1.2;
        font-weight: 700;
        opacity: .65;
        text-transform: uppercase;
        letter-spacing: .02em;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(1)::before { content: 'Takip'; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(2)::before { content: "{{ phrase('wrxt_hata_i18n_select') }}"; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(3)::before { content: 'Rapor'; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(4)::before { content: "{{ phrase('wrxt_hata_i18n_user') }}"; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(5)::before { content: "{{ phrase('wrxt_hata_i18n_category_context') }}"; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(6)::before { content: 'Durum'; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(7)::before { content: "{{ phrase('wrxt_hata_i18n_diagnostics') }}"; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(8)::before { content: 'Atanan'; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(9)::before { content: 'Tarih'; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(3) {
        grid-column: 1 / -1;
        order: -10;
        padding-top: 12px;
        padding-bottom: 12px;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(1) { order: -9; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(2) { order: -8; }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(8),
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(9) {
        border-bottom: 0;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(3) .u-muted {
        margin-top: 5px;
        line-height: 1.45;
        overflow-wrap: anywhere;
    }
    .wrxtHata-reportList .wrxtHata-categoryCell,
    .wrxtHata-reportList .wrxtHata-reportFlag {
        width: auto;
        min-width: 0;
        text-align: left;
    }
    .wrxtHata-reportList .wrxtHata-categoryCell .label {
        min-width: 0;
    }
}
@media (max-width: 340px) {
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow {
        grid-template-columns: 1fr;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(3) {
        grid-column: 1;
    }
    .wrxtHata-reportList .dataList-table .wrxtHata-reportRow > td:nth-child(8) {
        border-bottom: 1px solid @xf-borderColorLight;
    }
}
